+#ifndef __NXTMPDIR_ESP_HAL_3RDPARTY_NUTTX_INCLUDE_PLATFORM_OS_H
+#define __NXTMPDIR_ESP_HAL_3RDPARTY_NUTTX_INCLUDE_PLATFORM_OS_H
+
+/****************************************************************************
+ * Included Files
+ ****************************************************************************/
+
+#include "sdkconfig.h"
+#include <stddef.h>
+#include <stdint.h>
+#include <nuttx/clock.h>
+#include <nuttx/sched.h>
